css:
/* EV roadmap: three numbered step cards with an icon, title, subtitle and text. Every card comes
   from the `steps` prop (one repeated node), so adding or editing a step is a list row. */
.bz-section[data-bz-node="rm"]{background:#fff;padding-block:clamp(56px,6vw,96px)}
[data-bz-node="rm"] .bz-block{padding-block:0 var(--space-3)}
[data-bz-node="rm-h"] h2{margin-bottom:var(--space-5)}
[data-bz-node="rm-steps"]{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;counter-reset:rm}
[data-bz-node="rm-steps"]>.bz-col{grid-column:auto;counter-increment:rm;background:#f7f7f5;border:1px solid var(--line);border-top:4px solid var(--accent);padding:clamp(22px,2.4vw,32px);position:relative}
[data-bz-node="rm-steps"]>.bz-col::before{content:counter(rm);position:absolute;top:18px;right:20px;font:800 2rem/1 var(--font-heading);color:#e1e1de}
[data-bz-node^="rm-icon"] .bz-container,[data-bz-node^="rm-icon"] .bz-figure{padding:0;margin:0;max-width:none}
[data-bz-node^="rm-icon"]{margin-bottom:var(--space-3)}
[data-bz-node^="rm-icon"] img{width:64px;height:64px}
[data-bz-node^="rm-title"] h3{font:700 clamp(1rem,1.5vw,1.25rem)/1.2 var(--font-heading);text-transform:uppercase;margin:0 0 4px}
[data-bz-node^="rm-sub"] .bz-text p{font:700 .8125rem/1.4 var(--font-body)!important;color:var(--ink)!important;margin:0 0 var(--space-3)!important}
[data-bz-node^="rm-desc"] .bz-text p{font-size:.8125rem!important;line-height:1.8;color:#4a4945!important;margin:0!important}
@media (max-width:1100px){[data-bz-node="rm-steps"]{grid-template-columns:minmax(0,1fr)}[data-bz-node="rm-steps"]>.bz-col{grid-column:1/-1}}
